const { useState } = React;
const storageKey = 'lesson-demo:settings';
const defaultSettings = { theme: 'light', fontSize: 16 };

function Settings() {
  const [settings, setSettings] = useState(() => {
    console.log('저장소를 읽었습니다.');
    const saved = localStorage.getItem(storageKey);
    return saved ? JSON.parse(saved) : defaultSettings;
  });

  return (
    <section>
      <p>테마: {settings.theme} / 글자: {settings.fontSize}px</p>
      <button type="button" onClick={() => setSettings({ ...settings, theme: settings.theme === 'light' ? 'dark' : 'light' })}>테마 바꾸기</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Settings />);

